#include <string>
using namespace std;

class Solution {
public:
    int minOperations(string s) {
        int left = 0, right = (int)s.size() - 1;
        int flips = 0;
        while (left < right) {
            if (s[left] != s[right]) flips++;
            left++;
            right--;
        }
        return flips;
    }
};

class Solution {
    public int minOperations(String s) {
        int left = 0, right = s.length() - 1;
        int flips = 0;
        while (left < right) {
            if (s.charAt(left) != s.charAt(right)) flips++;
            left++;
            right--;
        }
        return flips;
    }
}

var minOperations = function(s) {
    let left = 0, right = s.length - 1;
    let flips = 0;
    while (left < right) {
        if (s[left] !== s[right]) flips++;
        left++;
        right--;
    }
    return flips;
};
